def _grant_runtime_privileges() -> None:
    """Grant the runtime role what it needs and nothing more."""
    role = op.get_context().opts.get("app_role", "stagevote_app")
    if not role.replace("_", "").isalnum():
        raise ValueError(f"unsafe role name: {role!r}")
    op.execute(
        f"""
        DO $$
        BEGIN
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{role}') THEN
                GRANT USAGE ON SCHEMA public TO {role};
                GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO {role};
                GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO {role};
                REVOKE UPDATE, DELETE, TRUNCATE ON votes FROM {role};
                REVOKE UPDATE, DELETE, TRUNCATE ON audit_log FROM {role};
                REVOKE ALL ON alembic_version FROM {role};
                GRANT SELECT ON alembic_version TO {role};
            ELSE
                RAISE NOTICE 'role {role} does not exist; skipping runtime grants';
            END IF;
        END
        $$
        """
    )


